view_rebind:
var a:i64[2]=[7,8];var b:i64[2]=[9,10];var p:i64[2]& = a;
recursive fn right()->i64[..3]{p .= b;return[7,8];}
fn main(){assert(p==right());assert(p .== &b);print("view_rebind");}

view_projected:
struct H{items:i64[2]}
recursive fn left()->H{return H{items:[7,8]};}
recursive fn value(a:i64[2]&)->i64{return a[1]-92;}
recursive fn right()->i64[..3]{var scratch:i64[2]=[99,100];return[7,value(scratch)];}
fn main(){assert(left().items==right());print("view_projected");}

view_early:
recursive fn left()->i64[2]{return[7,8];}
recursive fn right()->i64[..3]{return[7,8];}
recursive fn run(early:bool)->bool{return left()==({if early{return true;}right()});}
fn main(){assert(run(true));assert(run(false));print("view_early");}

view_reverse:
recursive fn fixed()->i64[2]{return[7,8];}
recursive fn limited()->i64[..3]{return[7,8];}
fn main(){assert(limited()==fixed());assert(!(limited()!=fixed()));print("view_reverse");}
